-- Standalone: refresh chase_standings with the real post-Kansas (round 4) result.
-- Round 4 'after' becomes the actual Kansas finish; rounds 5-10 'before'/'after'
-- carry that forward as the current placeholder until each race runs.
-- Safe to re-run; replaces the rows it touches.
begin;

delete from chase_standings where race_id = (select id from races where chase_round = 4) and phase = 'after';
delete from chase_standings where race_id = (select id from races where chase_round = 5);
delete from chase_standings where race_id = (select id from races where chase_round = 6);
delete from chase_standings where race_id = (select id from races where chase_round = 7);
delete from chase_standings where race_id = (select id from races where chase_round = 8);
delete from chase_standings where race_id = (select id from races where chase_round = 9);
delete from chase_standings where race_id = (select id from races where chase_round = 10);


commit;
